{
  "description": "The creature is shown in profile facing right, standing upright on two hind legs. It has the body, head, fur, and tail of a reddish-orange fox with a white chest, throat and belly, and the large feathered wings of a barn owl attached to its sides. The fur is dense and reddish-brown on the back, sides and tail, lighter grey-white on the underside and chest, and the wings are broad with mottled tan, white, grey and black-spotted plumage. The neck and upper back are covered in small overlapping reddish feather-like scales that blend into the fur. The overall posture is bipedal, with the bushy fox tail hanging behind the legs and the wings held slightly away from the body.",
  "parts": [
    {
      "part": "head",
      "looks_like": "fox-like head at the front of the body, with a pointed muzzle, black nose, yellow eyes with dark pupils, white fur on the muzzle, chin and lower cheek, reddish-orange fur on the top and sides, and fine whiskers on the muzzle",
      "where": "at the anterior end, atop the neck, facing right"
    },
    {
      "part": "ears",
      "looks_like": "two upright, triangular pointed ears with reddish-orange outer fur and black and white inner fur, with dark tips",
      "where": "on top of the head, one more forward and one slightly behind"
    },
    {
      "part": "legs",
      "looks_like": "two muscular hind legs covered in reddish-brown fur on the outer side and grey-white fur on the inner thigh, jointed in a digitigrade stance",
      "where": "underneath the body, extending from the lower torso to the ground, supporting the standing posture"
    },
    {
      "part": "feet",
      "looks_like": "two paw-like feet with dark brown to black fur, visible toe pads and short claws",
      "where": "at the ends of the two legs, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "one long, thick, bushy tail covered in dense reddish-brown fur, slightly lighter at the tip, with a fluffy texture",
      "where": "at the rear of the body, extending down behind the legs"
    },
    {
      "part": "wings",
      "looks_like": "two large broad wings with layered flight feathers, patterned in tan, cream-white, grey and black with dark spots and bars, the upper wing coverts mottled grey and tan",
      "where": "one on each side of the torso, the right wing (viewer left) seen in full side view and the left wing (viewer right) partially visible behind the chest"
    },
    {
      "part": "feathers",
      "looks_like": "dense overlapping feathers; small scale-like reddish-brown feathers on the neck and upper back, and larger barred and spotted flight and covert feathers on the wings in white, tan, grey and black",
      "where": "covering the wings entirely and the dorsal neck and upper back, blending into the fur"
    },
    {
      "part": "scales",
      "looks_like": "small overlapping scale-like plates formed by the neck feathers, reddish-brown with darker edges, arranged in rows",
      "where": "along the back of the neck and onto the upper back between the head and the wings"
    },
    {
      "part": "markings",
      "looks_like": "white chest and belly fur contrasting with reddish back, black on the back of the ears, dark spotting and barring on the wing feathers, and a black nose",
      "where": "white on the throat, chest and inner legs; dark spots/bars across the wing surfaces; black on ear backs and nose"
    }
  ],
  "attached_objects": [],
  "animals": ["fox", "owl"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 2,
  "wings": 2,
  "extra_limb_pieces": 0,
  "tails": 1
}
